def translations():
    result = {}
    for lang, row in ROWS.items():
        values = row.split('|')
        if len(values) != len(KEYS):
            raise ValueError((lang, len(values), len(KEYS)))
        result[lang] = dict(zip(KEYS, values))
    result['ro']['phone'] = 'Număr de telefon'
    return result
